import math

def control(obs):
    h=obs['hitch_deg']
    pts=[]
    for name in ('direct','periphery'):
        v=obs.get('views',{}).get(name)
        if not v: continue
        ox,oy=v['origin']
        for b,d in v.get('walls',[]):
            a=math.radians(b); x=ox+d*math.cos(a); y=oy+d*math.sin(a)
            if -3.5<x<-0.6 and abs(y)<3: pts.append((x,y))
    left=[y for x,y in pts if y>0]
    right=[y for x,y in pts if y<0]
    bias=0
    if left and right:
        bias=max(-8,min(8,4*(min(left)+max(right))))
    steer=max(-35,min(35,2.2*h+bias))
    return (steer,-0.45,170)

